import java.util.List;
import java.util.Arrays;

class TestClass {
    List<Object> items;
    public TestClass(List<Object> list) {
        this.items = list;
    }
    public void process() {
        // Should NOT match because it uses .size() (method call) instead of .length (array field)
        for (int i = 0; i < items.size(); i++) {
            System.out.println(items.get(i));
        }
    }
}

